// Route incoming Telegram update - message vs callback_query.

const body = $input.first().json;

// Owner-only gate: this bot writes to a real tax sheet and spends OpenAI credits per
// message, so anyone who finds the bot handle must not be able to use it.
// Set owner_chat_ids in the Config node, comma separated. It is EMPTY by
// default and an empty list denies everyone: this bot writes to a real tax
// sheet and spends OpenAI credits per message, so a public bot handle with no
// gate would let a stranger use both. Failing closed is the safe default.
const cfg = $('⚙️ Config').first().json || {};
const ALLOWED_CHAT_IDS = String(cfg.owner_chat_ids || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const isAllowed = (id) => ALLOWED_CHAT_IDS.includes(String(id));

// CALLBACK QUERY: user tapped an inline button
if (body.callback_query) {
  const cb = body.callback_query;
  const cbChatId = String(cb.message?.chat?.id || cb.from?.id);
  if (!isAllowed(cbChatId)) return [{ json: { eventType: 'ignore', chatId: '0' } }];
  return [{
    json: {
      eventType: 'callback',
      callbackId: cb.id,
      callbackData: cb.data || '',
      chatId: cbChatId,
      messageId: cb.message?.message_id,
      fromUser: cb.from ? (cb.from.first_name + ' ' + (cb.from.last_name || '')).trim() : 'unknown'
    }
  }];
}

// MESSAGE: photo, voice, text, etc.
const message = body.message;
if (!message) {
  return [{ json: { eventType: 'ignore', chatId: '0' } }];
}

const chatId = String(message.chat.id);
if (!isAllowed(chatId)) return [{ json: { eventType: 'ignore', chatId: '0' } }];
const replyTo = message.reply_to_message || null;
const replyToText = replyTo?.text || '';

// Try to extract a trackingId from the replied message (format: EXP-YYYYMMDD-HHMMSS)
let replyTrackingId = null;
if (replyToText) {
  const m = replyToText.match(/EXP-\d{8}-\d{6}(?:-[a-z0-9]{4})?/);
  if (m) replyTrackingId = m[0];
}

let eventType = 'unsupported';
let photoFileId = null;
let voiceFileId = null;

if (message.photo && message.photo.length > 0) {
  eventType = 'photo';
  photoFileId = message.photo[message.photo.length - 1].file_id;
} else if (message.voice) {
  eventType = replyTrackingId ? 'voice_reply' : 'voice_standalone';
  voiceFileId = message.voice.file_id;
} else if (message.text) {
  eventType = replyTrackingId ? 'text_reply' : 'text_standalone';
}

return [{
  json: {
    eventType,
    chatId,
    messageId: message.message_id,
    text: message.text || '',
    caption: message.caption || '',
    photoFileId,
    voiceFileId,
    replyTrackingId,
    receivedAt: new Date().toISOString()
  }
}];

// Build OpenAI vision request. Magic-byte detection.

const route = $('Route Event').item.json;
const chatId = route.chatId;
const caption = route.caption || '';

const inItem = $input.first();
const binaryKey = Object.keys(inItem.binary || {})[0];
if (!binaryKey) throw new Error('No binary data from Telegram download.');

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const head = buffer.slice(0, 12);

let mimeType;
if (head[0] === 0xFF && head[1] === 0xD8 && head[2] === 0xFF) mimeType = 'image/jpeg';
else if (head[0] === 0x89 && head[1] === 0x50 && head[2] === 0x4E && head[3] === 0x47) mimeType = 'image/png';
else if (head[0] === 0x47 && head[1] === 0x49 && head[2] === 0x46) mimeType = 'image/gif';
else if (head.slice(0,4).toString('ascii') === 'RIFF' && head.slice(8,12).toString('ascii') === 'WEBP') mimeType = 'image/webp';
else if (head[4] === 0x66 && head[5] === 0x74 && head[6] === 0x79 && head[7] === 0x70) {
  throw new Error('HEIC/HEIF not supported. Disable iPhone "High Efficiency" or convert to JPEG.');
} else {
  throw new Error('Unrecognised image format. Magic bytes: ' + head.toString('hex'));
}

const base64Image = buffer.toString('base64');

const extractionPrompt = `Extract this German receipt as JSON, no markdown.

Schema:
{merchantName, merchantAddress, merchantCountry (ISO 3166-1 alpha-2, e.g. "DE", "IT", "US"; best guess from the merchant address, currency, and receipt language; "" if unknown), receiptDate (YYYY-MM-DD), grossAmount, netAmount, vatAmount, vatRate ("19"/"7"/"0"/"mixed"), currency (ISO, default "EUR"), paymentMethod ("Card"/"Cash"/"Bank Transfer"/"Unknown"), lineItems (brief), isInvoice (bool), isBelow250 (bool), tipAmount (number, 0 if no separately-noted Trinkgeld/tip line is visible on the receipt), confidenceScore ("High"/"Medium"/"Low"), needsReview (bool), unreadable (bool), notes}

Rules:
- German decimals use comma -> dot (12,50 -> 12.50)
- MwSt/USt = VAT. DE: standard 19%, reduced 7%
- DD.MM.YYYY -> YYYY-MM-DD
- If only gross + rate shown: net = gross / (1 + rate/100)
- PAYMENT METHOD: Default to "Card" unless receipt clearly indicates otherwise. The user almost always pays by card. Set to "Cash" ONLY if you see "Bar", "Barzahlung", "BAR", or "Cash" explicitly, AND it's a small purchase at a likely cash venue (cafe, market stall). Set to "Bank Transfer" if it's a Rechnung with IBAN/Überweisung. Card indicators: "EC-Karte", "Mastercard", "Visa", "Karte", "girocard", partial card number like **** 1234, "kontaktlos", signature line, terminal receipt format. When ambiguous: "Card".
- Set unreadable=true ONLY if you genuinely cannot read merchant AND amount`;

const requestBody = {
  model: 'gpt-4o-mini',
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: extractionPrompt },
      { type: 'image_url', image_url: { url: `data:${mimeType};base64,${base64Image}`, detail: 'high' } }
    ]
  }],
  max_completion_tokens: 1400,
  response_format: { type: 'json_object' }
};

return [{ json: { chatId, caption, requestBody } }];

// Parse vision response. Re-attach binary so Drive can use it later.

const priorJson = $('Prep Vision Payload').item.json;
const chatId = priorJson.chatId;
const caption = priorJson.caption;

const response = $input.first().json;
const rawText = response?.choices?.[0]?.message?.content || '';
const cleaned = rawText.replace(/```json\s*/gi, '').replace(/```\s*$/g, '').trim();

let vision = {};
try { vision = JSON.parse(cleaned); }
catch (e) {
  vision = { unreadable: true, needsReview: true, confidenceScore: 'Low', notes: 'Failed to parse: ' + e.message };
}

// Check: do we have enough to log this?
const hasMinimum = vision.merchantName && vision.grossAmount && !vision.unreadable;
const isReadable = hasMinimum;

const tgItem = $('Download Photo').first();
return [{
  json: { chatId, caption, vision, isReadable },
  binary: tgItem.binary
}];

// Build the unreadable message text.
const j = $('Parse Vision').item.json;
const vision = j.vision || {};
const esc = (s) => String(s ?? '').replace(/<br\s*\/?>/gi,'\n').replace(/<\/?p>/gi,'\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const reasons = [];
if (!vision.merchantName) reasons.push('merchant name');
if (!vision.grossAmount) reasons.push('amount');
if (vision.unreadable) reasons.push('overall image quality');
if (vision.notes) reasons.push(esc(vision.notes));

return [{
  json: {
    chatId: j.chatId,
    errorText: `⚠️ I couldn't read this receipt well enough to log it.\n\nMissing/unclear: ${esc(reasons.join(', '))}\n\n📸 Please send a clearer photo (good lighting, flat surface, no shadows).`
  }
}];

// Build a descriptive filename. Carry vision data + binary forward.

const j = $('Parse Vision').item.json;
const vision = j.vision || {};

const sanitize = (s) => String(s || '')
  .replace(/[\\\/:*?"<>|]/g, '')
  .replace(/\s+/g, '_')
  .replace(/[^\w\-äöüÄÖÜß]/g, '')
  .substring(0, 30)
  .replace(/_+$/, '')
  .trim();

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const todayStr = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
const timeStr = `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

let dateStr = todayStr;
if (vision.receiptDate) {
  const d = new Date(vision.receiptDate);
  if (!isNaN(d.getTime())) dateStr = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
}

const merchant = sanitize(vision.merchantName) || 'UnknownMerchant';
const amount = vision.grossAmount ? String(vision.grossAmount).replace(',', '.').replace(/[^0-9.]/g, '') + 'EUR' : '';
const parts = [dateStr, merchant];
if (amount) parts.push(amount);
parts.push(timeStr);
const filename = parts.join('_') + '.jpg';

const tgItem = $('Download Photo').first();
return [{
  json: { chatId: j.chatId, caption: j.caption, vision: j.vision, filename },
  binary: tgItem.binary
}];

// Parse classification, build Ausgaben row, build confirmation message with smart context prompts.
const esc = (s) => String(s ?? '').replace(/<br\s*\/?>/gi,'\n').replace(/<\/?p>/gi,'\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ── Universal German-tax expense engine ─────────────────────────────────────
// base = NET when German input VAT is recoverable, else GROSS.
// deductibleAmount = base x deductibility% (income-tax Betriebsausgabe).
// recoverableVAT   = full VAT at 100% if recoverable & not blocked, else 0 (Vorsteuer).
function computeExpenseTax({ gross, net, vatAmount, vatRate,
                             deductibilityPct, hasRecoverableGermanVAT, vatBlocked }) {
  const toNum = (v) => {
    if (v === null || v === undefined || v === '') return null;
    const n = parseFloat(String(v).replace(',', '.').replace(/[^0-9.\-]/g, ''));
    return isNaN(n) ? null : n;
  };
  const g = toNum(gross);
  let   n = toNum(net);
  const vat = toNum(vatAmount);
  const rateNum = (() => {
    const r = parseFloat(String(vatRate ?? '').replace(/[^0-9.]/g, ''));
    return isNaN(r) ? null : r;
  })();
  const pct = toNum(deductibilityPct) ?? 100;
  const germanVAT = hasRecoverableGermanVAT === true;
  const blocked   = vatBlocked === true;

  // If German VAT is recoverable but net wasn't read, derive it.
  if (germanVAT && n === null && g !== null) {
    if (rateNum)        n = +(g / (1 + rateNum / 100)).toFixed(2);
    else if (vat !== null) n = +(g - vat).toFixed(2);
  }

  const base           = (germanVAT && n !== null) ? n : g;
  const deductibleAmount = (base !== null) ? +(base * pct / 100).toFixed(2) : null;
  const recoverableVAT   = (germanVAT && !blocked && vat !== null) ? vat : 0;
  const deductionBase    = (germanVAT && n !== null) ? 'net' : 'gross';

  // Derived reporting splits.
  // netDeductible    = the part of the base you actually get to deduct.
  // netNonDeductible = the part you lose (e.g. the 30% of a Bewirtung meal).
  // vatDeductible    = the Vorsteuer, same figure as recoverableVAT, named for the sheet.
  // totalDeductibleExpense = deduction + reclaimable VAT, the full euro benefit.
  const netDeductible = deductibleAmount;
  const netNonDeductible = (base === null || deductibleAmount === null)
    ? null : +(base - deductibleAmount).toFixed(2);
  const vatDeductible = recoverableVAT;
  const totalDeductibleExpense = (deductibleAmount === null)
    ? null : +(deductibleAmount + recoverableVAT).toFixed(2);

  return { netUsed: n, base, deductibleAmount, recoverableVAT, deductionBase,
           netDeductible, netNonDeductible, vatDeductible, totalDeductibleExpense };
}

const priorJson = $('Build Classify Payload').item.json;
const chatId = priorJson.chatId;
const vision = priorJson.vision || {};
const caption = priorJson.caption || '';
const imageUrl = priorJson.imageUrl || '';

const response = $input.first().json;
const rawText = response?.choices?.[0]?.message?.content || '';
const cleaned = rawText.replace(/```json\s*/gi, '').replace(/```\s*$/g, '').trim();

let cls = {};
try { cls = JSON.parse(cleaned); }
catch (e) {
  cls = {
    costCenter: 'Sonstiges',
    germanTaxCategory: 'Sonstige Betriebsausgaben',
    description: vision.lineItems || 'Unparseable',
    businessPurpose: caption || '',
    attendees: '',
    deductibility: 100,
    taxNotes: 'Failed to parse classifier: ' + e.message,
    missingForTax: ['classification'],
    confidenceScore: 'Low',
    needsReview: true
  };
}

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const rand = Math.random().toString(36).slice(2, 6); // 4 chars, e.g. "k7d2"
const trackingId = `EXP-${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}`
                 + `-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
                 + `-${rand}`;
const trackedDate = `${pad(now.getDate())}.${pad(now.getMonth()+1)}.${now.getFullYear()}`;

let receiptDate = '';
if (vision.receiptDate) {
  const d = new Date(vision.receiptDate);
  if (!isNaN(d.getTime())) receiptDate = `${pad(d.getDate())}.${pad(d.getMonth()+1)}.${d.getFullYear()}`;
  else receiptDate = String(vision.receiptDate);
}

const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).replace(',', '.').replace(/[^0-9.\-]/g, '');
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
};

const gross = toNum(vision.grossAmount);
const net = toNum(vision.netAmount);
const vatAmt = toNum(vision.vatAmount);
const vatRate = vision.vatRate ? String(vision.vatRate) + '%' : '';
const deductibilityPct = toNum(cls.deductibility) ?? 100;

const tax = computeExpenseTax({
  gross, net, vatAmount: vatAmt, vatRate: vision.vatRate,
  deductibilityPct,
  hasRecoverableGermanVAT: cls.hasRecoverableGermanVAT,
  vatBlocked: cls.vatBlocked,
});
const deductibleAmount = (tax.deductibleAmount !== null) ? tax.deductibleAmount : '';
const currency = vision.currency || 'EUR';
const needsFxConversion = currency !== 'EUR';

const needsReview = (vision.needsReview || cls.needsReview || needsFxConversion) ? 'Yes' : 'No';
const confidence = (() => {
  const order = { 'Low': 0, 'Medium': 1, 'High': 2 };
  const a = order[vision.confidenceScore] ?? 1;
  const b = order[cls.confidenceScore] ?? 1;
  return ['Low', 'Medium', 'High'][Math.min(a, b)];
})();

const row = {
  trackingId,
  receiptDate,
  trackedDate,
  merchantName: vision.merchantName || '',
  description: cls.description || vision.lineItems || '',
  additionalContext: caption,
  costCenter: cls.costCenter || 'Sonstiges',
  germanTaxCategory: cls.germanTaxCategory || 'Sonstige Betriebsausgaben',
  netAmount: net !== null ? net : '',
  vatRate,
  vatAmount: vatAmt !== null ? vatAmt : '',
  grossAmount: gross !== null ? gross : '',
  currency,
  deductibility: deductibilityPct + '%',
  deductibleAmount,
  vatCountry: cls.merchantCountry || vision.merchantCountry || '',
  deductionBase: tax.deductionBase,
  recoverableVAT: tax.recoverableVAT,
  needsFxConversion: needsFxConversion ? 'Yes' : 'No',
  tipAmount: (toNum(vision.tipAmount) !== null) ? toNum(vision.tipAmount) : 0,
  vatDeductible: tax.vatDeductible,
  netDeductible: (tax.netDeductible !== null) ? tax.netDeductible : '',
  netNonDeductible: (tax.netNonDeductible !== null) ? tax.netNonDeductible : '',
  totalDeductibleExpense: (tax.totalDeductibleExpense !== null) ? tax.totalDeductibleExpense : '',
  paymentMethod: vision.paymentMethod || 'Unknown',
  businessPurpose: cls.businessPurpose || '',
  attendees: cls.attendees || '',
  taxNotes: (cls.taxNotes || '') + (needsFxConversion ? ' Fremdwaehrung - im Steuerpaket zum EZB-Referenzkurs des Zahlungstages in EUR umrechnen.' : ''),
  imageUrl,
  confidenceScore: confidence,
  needsReview
};

// Build smart "what's missing for tax purposes" prompts per cost center
const cc = row.costCenter;
const missing = cls.missingForTax || [];
let contextHint = '';
if (cc === 'Bewirtungskosten') {
  contextHint = '\n\n🧾 <b>Für Bewirtungskosten (German tax law):</b>\n• 👥 Wer war dabei? (Namen)\n• 🎯 Anlass / Geschäftszweck?\n• 📍 Ort (>€250)?';
} else if (cc === 'Reisekosten') {
  contextHint = '\n\n🧾 <b>Für Reisekosten:</b>\n• 🎯 Reisezweck?\n• 📍 Ziel & Daten?\n• 👥 Geschäftskontakte involviert?';
} else if (cc === 'Kommunikation & IT') {
  contextHint = '\n\n🧾 <b>Für IT/Software:</b>\n• 📝 Wofür wird es im Business genutzt?';
} else if (cc === 'Marketing & Werbung') {
  contextHint = '\n\n🧾 <b>Für Marketing:</b>\n• 📝 Welche Kampagne / welcher Kunde?\n• 🎯 Ad spend, Creative, Stock?';
} else if (cc === 'Beratung & Coaching') {
  contextHint = '\n\n🧾 <b>Für Beratung/Coaching:</b>\n• 🎯 Thema / Zweck?\n• 👥 Berater/Coach Name?';
} else if (cc === '(Digitale) Produktentwicklung') {
  contextHint = '\n\n🧾 <b>Für Produktentwicklung:</b>\n• 📝 Welches Projekt?\n• 👥 Welcher Freelancer / welche Agentur?';
} else if (cc === 'Büro & Infrastruktur') {
  contextHint = '\n\n🧾 <b>Für Büro:</b>\n• 📝 Was wurde gekauft und wofür?';
} else {
  contextHint = '\n\n🧾 Anything to add about this expense?';
}

const sheetUrl = String(($('⚙️ Config').first().json || {}).sheet_url || '');

const doneText = `✅ Logged: ${esc(trackingId)}\n\n🏪 ${esc(row.merchantName)}\n💶 €${esc(row.grossAmount)} ${esc(row.currency)}\n📅 ${esc(row.receiptDate)}\n\n📁 ${esc(row.costCenter)}\n💰 ${esc(row.deductibility)} = €${esc(row.deductibleAmount)}\n${row.businessPurpose ? '🎯 ' + esc(row.businessPurpose) + '\n' : ''}${row.attendees ? '👥 ' + esc(row.attendees) + '\n' : ''}\n📊 Confidence: ${esc(confidence)} | Review needed: ${esc(needsReview)}${contextHint}`;

// Inline keyboard JSON for Telegram
const inlineKeyboard = {
  inline_keyboard: [
    [
      { text: '➕ Add context', callback_data: `add:${trackingId}` },
      { text: '⏭️ Skip', callback_data: `skip:${trackingId}` }
    ],
    [
      { text: '🗑️ Delete & Redo', callback_data: `del:${trackingId}` },
      { text: '🔗 View Sheet', url: sheetUrl }
    ]
  ]
};

return [{
  json: {
    ...row,
    chatId,
    doneText,
    inlineKeyboardJson: JSON.stringify(inlineKeyboard)
  }
}];

// Duplicate guard. People re-photograph the same receipt fairly often; before this
// the row was appended twice with no hint. We do NOT auto-discard: a real second
// visit to the same restaurant for the same amount is possible, so this only
// raises a warning and lets him decide.
const row = $('Build Final Row').first().json;

// The Sheets read is a non-passthrough node (rule 12), so `row` comes from the
// named node above, and the existing rows come from this node's own input.
const existing = $input.all().map(i => i.json).filter(r => r && r['Tracking ID']);

const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g,'');
const money = v => {
  const n = parseFloat(String(v ?? '').replace(',','.'));
  return Number.isFinite(n) ? Math.round(n*100)/100 : null;
};
// Sheet dates are DD.MM.YYYY
const asDate = s => {
  const m = String(s ?? '').match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return m ? Date.UTC(+m[3], +m[2]-1, +m[1]) : null;
};

const newMerchant = norm(row.merchantName);
const newGross    = money(row.grossAmount);
const newDate     = asDate(row.receiptDate);
const DAY = 86400000;

let match = null;
if (newMerchant && newGross !== null) {
  for (const r of existing) {
    if (String(r['Tracking ID']) === String(row.trackingId)) continue;  // never match self
    if (norm(r['Merchant Name']) !== newMerchant) continue;
    if (money(r['Gross Amount']) !== newGross) continue;
    const d = asDate(r['Receipt Date']);
    // same amount at the same merchant within 3 days is almost always a re-upload
    const near = (newDate !== null && d !== null) ? Math.abs(newDate - d) <= 3*DAY : true;
    if (!near) continue;
    match = r;
    break;
  }
}

if (!match) {
  return [{ json: { ...row, isDupe: false } }];
}

// Stash the full row so "Add anyway" can append it after the button tap.
const sd = $getWorkflowStaticData('global');
sd['dupe_' + row.trackingId] = { row, stashedAt: Date.now() };
// keep the stash from growing forever
for (const k of Object.keys(sd)) {
  if (k.startsWith('dupe_') && sd[k] && (Date.now() - (sd[k].stashedAt||0)) > 7*24*3600*1000) delete sd[k];
}

return [{ json: { ...row, isDupe: true,
  dupeOfId: match['Tracking ID'], dupeOfDate: match['Receipt Date'],
  dupeOfCostCenter: match['Cost Center'] || '', dupeOfTracked: match['Tracked Date'] || '' } }];

const esc = s => String(s ?? '').replace(/<br\s*\/?>/gi,'\n').replace(/<\/?p>/gi,'\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const j = $input.first().json;
const text =
`⚠️ <b>Looks like a duplicate, not logged yet.</b>

🏪 ${esc(j.merchantName)}
💶 €${esc(j.grossAmount)} ${esc(j.currency)}
📅 ${esc(j.receiptDate)}

Already in the sheet as <b>${esc(j.dupeOfId)}</b>${j.dupeOfDate ? ' (receipt dated ' + esc(j.dupeOfDate) + ')' : ''}${j.dupeOfCostCenter ? ', booked as ' + esc(j.dupeOfCostCenter) : ''}.

Nothing has been written. Add it anyway if this really is a separate expense.`;
return [{ json: { chatId: j.chatId, trackingId: j.trackingId, dupeText: text } }];

// Append to Ausgaben now has TWO entry paths (normal photo flow, and "Add anyway"
// after a duplicate warning). Per the multi-entry rule, do not hard-reference a
// node that only exists on one of them.
let src;
try { src = $('Build Final Row').first().json; }
catch (e) { src = $('Recall Dupe Row').first().json; }
return [{ json: src }];

// User replied with text to a bot message, but we only accept voice for refines.

const r = $('Route Event').item.json;
return [{
  json: {
    chatId: r.chatId,
    errorText: '🎤 Please send a <b>voice note</b> (not text) to refine.\n\nTap and hold the mic, swipe up to lock recording.'
  }
}];

// Validate this voice came as reply to a bot message with a trackingId.

const r = $('Route Event').item.json;
const replyTrackingId = r.replyTrackingId;
const chatId = r.chatId;
const voiceFileId = r.voiceFileId;

if (!replyTrackingId) {
  return [{
    json: {
      valid: false,
      chatId,
      errorText: `🎤 I got your voice note, but I'm not sure which receipt it's for.\n\nTo add context, <b>reply to</b> my "✅ Logged: EXP-..." message, or tap "➕ Add context" first.`
    }
  }];
}

return [{
  json: {
    valid: true,
    chatId,
    trackingId: replyTrackingId,
    voiceFileId
  }
}];

const target = $('Parse Voice Reply').item.json.trackingId;
const allRows = $input.all();

// Find column name that contains 'tracking' and 'id' (case-insensitive)
// With alwaysOutputData the node can now receive a single blank item, which means
